//! Reads stores generated by the upstream C++ MMKV v2.4.3.
//!
//! The binaries under `tests/fixtures/` were produced by
//! `Core/cbridge/MMKVBridge.h` against `MMKV/Core` (see `fixtures/README.md`).
//! No C++ toolchain is needed to run this test.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use mmkv_core::{CryptKey, Mode, Store, StoreConfig};
use mmkv_platform_macos::MacPlatform;

fn fixtures_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn open(id: &str, mode: Mode, key: Option<(&CryptKey, bool)>) -> Arc<Store> {
    let platform = Arc::new(MacPlatform::new());
    let mut config = StoreConfig::new().mode(mode);
    if let Some((key, aes256)) = key {
        config = config.crypt_key(key, aes256);
    }
    Store::open_at(platform, &fixtures_root(), id, &config)
        .unwrap_or_else(|error| panic!("open {id}: {error}"))
}

#[test]
fn plain_basic_matches_cpp() {
    let store = open("plain_basic", Mode::READ_ONLY, None);
    assert!(store.get_bool("bool", false));
    assert_eq!(store.get_i32("i32", 0), -42);
    assert_eq!(store.get_u32("u32", 0), 3_000_000_000);
    assert_eq!(store.get_i64("i64", 0), -9_000_000_000);
    assert_eq!(store.get_u64("u64", 0), u64::MAX);
    assert_eq!(store.get_f32("f32", 0.0), 3.5);
    assert_eq!(store.get_f64("f64", 0.0), -2.25);
    assert_eq!(store.get_str("str").as_deref(), Some("hello 中文"));
    assert_eq!(store.get_str("empty").as_deref(), Some(""));
    assert_eq!(store.get_bytes("bytes"), Some(vec![0, 1, 2, 255]));
    assert_eq!(store.get_bytes("empty_bytes"), Some(Vec::new()));
    assert_eq!(store.get_str("long").map(|value| value.len()), Some(10_000));
    assert_eq!(store.get_str("removed"), None);
    assert_eq!(store.count(), 12);
    assert!(!store.is_encryption_enabled());
    assert!(store.actual_size() > 10_000);
    assert!(Store::is_file_valid("plain_basic", &fixtures_root()));
}

#[test]
fn plain_bulk_matches_cpp() {
    let store = open("plain_bulk", Mode::READ_ONLY, None);
    assert_eq!(store.count(), 200);
    let expected = "v".repeat(300);
    for index in 0..200 {
        assert_eq!(
            store.get_str(&format!("k{index:03}")).as_deref(),
            Some(expected.as_str())
        );
    }
}

#[test]
fn special_character_fixture() {
    let store = open("fixture/a:b", Mode::READ_ONLY, None);
    assert_eq!(store.get_str("key").as_deref(), Some("value"));
    assert_eq!(store.count(), 1);
    assert!(Store::exists("fixture/a:b", &fixtures_root()));
}

#[test]
fn trimmed_and_cleared_fixtures() {
    let trimmed = open("plain_trim", Mode::READ_ONLY, None);
    assert_eq!(trimmed.count(), 20);
    assert_eq!(trimmed.get_str("k499").map(|value| value.len()), Some(300));
    assert_eq!(trimmed.get_str("k000"), None);

    let cleared = open("plain_clear", Mode::READ_ONLY, None);
    assert_eq!(cleared.count(), 0);
    assert_eq!(cleared.actual_size(), 0);
    assert_eq!(cleared.get_str("key"), None);
}

#[test]
fn crypt128_matches_cpp() {
    let key = CryptKey::new(b"0123456789abcdef".to_vec());
    let store = open("crypt128", Mode::READ_ONLY, Some((&key, false)));
    assert!(store.is_encryption_enabled());
    assert!(store.get_bool("bool", false));
    assert_eq!(store.get_i32("i32", 0), 123_456);
    assert_eq!(store.get_str("small").as_deref(), Some("crypt-small"));
    assert_eq!(
        store.get_str("large").as_deref(),
        Some("C".repeat(5_000).as_str())
    );
    assert_eq!(store.get_bytes("bytes"), Some(vec![1, 2, 3, 4, 5]));
    assert_eq!(store.get_str("removed"), None);
    assert_eq!(store.count(), 5);
    let mut keys = store.all_keys();
    keys.sort();
    assert_eq!(
        keys,
        vec![
            "bool".to_owned(),
            "bytes".to_owned(),
            "i32".to_owned(),
            "large".to_owned(),
            "small".to_owned()
        ]
    );

    // value_size / write_value must operate on decrypted values.
    assert_eq!(store.value_size("small", false), 1 + "crypt-small".len());
    assert_eq!(store.value_size("small", true), "crypt-small".len());
    let mut buffer = vec![0u8; "crypt-small".len()];
    assert_eq!(
        store.write_value("small", &mut buffer).unwrap(),
        "crypt-small".len()
    );
    assert_eq!(&buffer, b"crypt-small");
}

#[test]
fn crypt256_matches_cpp() {
    let key = CryptKey::new(b"0123456789abcdef0123456789abcdef".to_vec());
    let store = open("crypt256", Mode::READ_ONLY, Some((&key, true)));
    assert_eq!(store.get_str("small").as_deref(), Some("aes256"));
    assert_eq!(
        store.get_str("large").as_deref(),
        Some("D".repeat(1_000).as_str())
    );
    assert_eq!(store.get_i32("i32", 0), 7);
    assert_eq!(store.count(), 3);
}

#[test]
fn crypt_single_key_updates_match_cpp() {
    let key = CryptKey::new(b"0123456789abcdef".to_vec());
    let store = open("crypt_single", Mode::READ_ONLY, Some((&key, false)));
    assert_eq!(store.get_str("only").as_deref(), Some("value-24"));
    assert_eq!(store.count(), 1);
}

#[test]
fn crypt_bulk_matches_cpp() {
    let key = CryptKey::new(b"0123456789abcdef".to_vec());
    let store = open("crypt_bulk", Mode::READ_ONLY, Some((&key, false)));
    assert_eq!(store.count(), 300);
    let expected = "B".repeat(300);
    for index in 0..300 {
        assert_eq!(
            store.get_str(&format!("k{index:03}")).as_deref(),
            Some(expected.as_str())
        );
    }
}

#[test]
fn expired_fixture() {
    let store = open("expire", Mode::READ_ONLY, None);
    assert!(store.is_expiration_enabled());
    assert_eq!(store.get_str("keep").as_deref(), Some("keep"));
    assert_eq!(store.get_i32("num", 0), 42);
    assert_eq!(store.get_i32("gone", -1), -1);
    assert_eq!(store.count(), 3);
    assert_eq!(store.count_non_expired(), 2);
    let mut keys = store.all_keys_non_expired();
    keys.sort();
    assert_eq!(keys, vec!["keep".to_owned(), "num".to_owned()]);
}
